// build.js の図を、Google Slides API の batchUpdate の要求に変換する。
// build.js が呼ぶ pptxgenjs の代わりに、呼び出しを記録する偽物を読み込ませ、
// 記録した図形を要求に変換して、スライドの範囲ごとに JSON のファイルに書き出す。
//
// 実行: node gslides.js <出力ディレクトリ> <最初のスライド>-<最後のスライド> [--rgb] [--master <id>] [--delete <id>]
//   --rgb     テーマの色を参照せず、RGB の値で書く（マスターの配色を変えられないとき）
//   --master  マスターの objectId。指定すると、マスターの配色をこの資料のテーマに変える要求を先頭に入れる
//   --delete  消すスライドの objectId（Drive が作った最初のスライド）
// ノートは別に書き出す: node gslides.js <出力ディレクトリ> notes <ノートの ID の JSON>
const fs = require("fs");
const path = require("path");
const Module = require("module");

const PT = 72; // 1 インチのポイント数
// Google スライドのテキストの内側の余白。API では変えられないので、余白 0 の文字の箱をこの分だけ広げる
const PAD_X = 0.1, PAD_Y = 0.05;
const FONT = "Noto Sans JP";
const BULLET_INDENT = 16; // 箇条書きの本文の字下げ（ポイント）

const SHAPES = {
  ROUNDED_RECTANGLE: "ROUND_RECTANGLE", RECTANGLE: "RECTANGLE", OVAL: "ELLIPSE",
  PENTAGON: "HOME_PLATE", CHEVRON: "CHEVRON", CAN: "CAN", LINE: "LINE",
};
const OVERLAY = new Set(["ELLIPSE", "CAN", "CHEVRON", "HOME_PLATE"]);
const SCHEME = {
  text1: "@DARK1", text2: "@DARK2", background1: "@LIGHT1", background2: "@LIGHT2",
  accent1: "@ACCENT1", accent2: "@ACCENT2", accent3: "@ACCENT3",
  accent4: "@ACCENT4", accent5: "@ACCENT5", accent6: "@ACCENT6",
};
const THEME_KEYS = {
  DARK1: "dk1", LIGHT1: "lt1", DARK2: "dk2", LIGHT2: "lt2",
  ACCENT1: "accent1", ACCENT2: "accent2", ACCENT3: "accent3",
  ACCENT4: "accent4", ACCENT5: "accent5", ACCENT6: "accent6",
  HYPERLINK: "hlink", FOLLOWED_HYPERLINK: "folHlink",
};

class FakeSlide {
  constructor(master) { this.master = master; this.items = []; this.notes = ""; }
  addText(t, o) { this.items.push({ kind: "text", t, o }); }
  addShape(type, o) { this.items.push({ kind: "shape", type, o }); }
  addNotes(t) { this.notes = t; }
}
class FakePptx {
  constructor() { this.slides = []; this.masters = {}; this.SchemeColor = SCHEME; this.shapes = SHAPES; }
  defineSlideMaster(m) { this.masters[m.title] = m; }
  addSection() {}
  addSlide({ masterName }) { const s = new FakeSlide(this.masters[masterName]); this.slides.push(s); return s; }
  async writeFile() {}
}

let captured = null;
const origLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (request === "pptxgenjs") return function () { const p = new FakePptx(); captured = { pres: p }; return p; };
  if (request.endsWith("apply_theme.js")) return { applyTheme: async (_f, theme) => { captured.theme = theme; } };
  return origLoad.apply(this, arguments);
};

// ---- 引数 ----
const [outDir, range, ...rest] = process.argv.slice(2);
const flag = (n) => rest.includes(n);
const opt = (n) => { const i = rest.indexOf(n); return i >= 0 ? rest[i + 1] : undefined; };
process.env.PPTX_SKILL_DIR = process.env.PPTX_SKILL_DIR || "/nonexistent";
process.argv = [process.argv[0], path.join(__dirname, "build.js"), "unused.pptx"];
require("./build.js");

setImmediate(async () => {
  await new Promise((r) => setTimeout(r, 50));
  const { pres, theme } = captured;
  fs.mkdirSync(outDir, { recursive: true });
  if (range === "notes") return writeNotes(pres, JSON.parse(fs.readFileSync(rest[0], "utf8")));
  const [a, b] = range.split("-").map(Number);
  const reqs = [];
  const master = opt("--master");
  if (master) reqs.push(colorSchemeRequest(master, theme));
  for (let n = a; n <= b; n++) reqs.push(...slideRequests(pres.slides[n - 1], n, theme, flag("--rgb")));
  const del = opt("--delete");
  if (del) reqs.push({ deleteObject: { objectId: del } });
  const file = path.join(outDir, `requests-${a}-${b}.json`);
  fs.writeFileSync(file, JSON.stringify(reqs));
